<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Service\Visibility\ClientIdentityVisibilityService;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentity;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ClientIdentityCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ClientIdentityVisibilityService $visibility,
        private readonly ClientIdentityWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Client identity");
        $span = $this->startSpan("Check allow of create usecase for Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(ClientIdentityCreateParams $params): ClientIdentityCreateResult
    {
        $this->logDebug("Run create usecase for Client identity");
        $span = $this->startSpan("Run create usecase for Client identity");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Client identity');
            }
            $this->dispatcher->dispatch(new ClientIdentityCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new ClientIdentityCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = ClientIdentity::create($input);
            $result = $this->writer->create(
                $entity,
                fn ($created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ClientIdentityCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
